/**
 * AutoSutra database schema (PostgreSQL, Drizzle ORM).
 *
 * Conventions
 * - Primary keys are UUIDs generated by Postgres.
 * - Money is stored as bigint minor units (paise) with an explicit currency.
 * - Every tenant-owned table carries organisation_id; services always filter on it.
 * - Append-only tables (audit_logs, ledger_entries, ledger_lines, campaign_approvals,
 *   payment_webhook_events, lead_activities) are protected by database triggers
 *   created in the migrations, so even a buggy service cannot rewrite history.
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  check,
  date,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const id = () => uuid("id").primaryKey().defaultRandom();
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const money = (name: string) => bigint(name, { mode: "number" });

