// ------------------------------------------------------------------ campaigns

export const campaigns = pgTable(
  "campaigns",
  {
    id: id(),
    organisationId: uuid("organisation_id")
      .notNull()
      .references(() => organisations.id, { onDelete: "restrict" }),
    dealershipId: uuid("dealership_id")
      .notNull()
      .references(() => dealerships.id, { onDelete: "restrict" }),
    primaryLocationId: uuid("primary_location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "restrict" }),
    name: text("name").notNull(),
    objective: campaignObjective("objective").notNull(),
    status: campaignStatus("status").notNull().default("draft"),
    templateId: uuid("template_id").references(() => creativeTemplates.id, { onDelete: "set null" }),
    // Product / offer
    brand: text("brand"),
    model: text("model"),
    variant: text("variant"),
    vehicleCategory: vehicleCategory("vehicle_category"),
    offerHeadline: text("offer_headline"),
    offerDetails: text("offer_details"),
    startingPrice: money("starting_price_paise"),
    priceVerified: boolean("price_verified").notNull().default(false),
    financeDetails: text("finance_details"),
    financeApproved: boolean("finance_approved").notNull().default(false),
    bookingUrl: text("booking_url"),
    disclaimer: text("disclaimer"),
    claimsStatus: claimStatus("claims_status").notNull().default("not_required"),
    claimsReviewedById: uuid("claims_reviewed_by_id").references(() => users.id),
    // Schedule
    startDate: date("start_date"),
    endDate: date("end_date"),
    // Budget controls (all in paise)
    maxAuthorisedSpend: money("max_authorised_spend_paise"),
    alertThresholdPct: integer("alert_threshold_pct").notNull().default(80),
    // Audience (provider-neutral)
    ageMin: integer("age_min").notNull().default(18),
    ageMax: integer("age_max").notNull().default(65),
    languages: text("languages").array().notNull().default(sql`'{}'::text[]`),
    placements: text("placements").notNull().default("automatic"),
    keywords: text("keywords").array().notNull().default(sql`'{}'::text[]`),
    // Workflow
    managed: boolean("managed").notNull().default(false),
    assignedManagerId: uuid("assigned_manager_id").references(() => users.id),
    createdById: uuid("created_by_id")
      .notNull()
      .references(() => users.id),
    submittedById: uuid("submitted_by_id").references(() => users.id),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    currentApprovalId: uuid("current_approval_id"),
    /** Incremented on every edit; approvals are bound to a version + config hash. */
    version: integer("version").notNull().default(1),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("campaigns_org_idx").on(t.organisationId),
    index("campaigns_status_idx").on(t.status),
    check("campaigns_age_chk", sql`${t.ageMin} >= 18 AND ${t.ageMax} <= 65 AND ${t.ageMin} <= ${t.ageMax}`),
    check("campaigns_threshold_chk", sql`${t.alertThresholdPct} BETWEEN 10 AND 100`),
  ],
);

